input.command:
mkdir -p scratch/capybara && cat > scratch/capybara/run.ts <<'E'
import * as THREE from "three";
import build from "../../samples/capybara";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
console.log("min", box.min.toArray().map(v=>+v.toFixed(3)), "max", box.max.toArray().map(v=>+v.toFixed(3)));
let meshes=0, tris=0, joints=0;
root.traverse((o:any)=>{ if(o.isMesh){meshes++; const g=o.geometry; tris += (g.index? g.index.count: g.attributes.position.count)/3;} if(o.isBone||o.userData?.joint) joints++; });
console.log({meshes,tris,joints});
E
timeout 120 npx tsx scratch/capybara/run.ts 2>&1 | tail -30
